const featuredArtCount=9;
const artCategoryNames={"type": "标志与字体", "graphic": "图形排版", "poster": "海报与封面", "packaging": "封面包装", "spatial": "视觉实验"};
const artDialog=document.querySelector('#art-dialog'),artCards=[...document.querySelectorAll('.art-card')];
let artCategory='all',artExpanded=false,viewerItems=artworks,artIndex=0,artTrigger=null;
function applyArtFilter(){const matches=artCards.filter(c=>artCategory==='all'||c.dataset.artCategory===artCategory);artCards.forEach(c=>{c.hidden=!matches.includes(c)||(artCategory==='all'&&!artExpanded&&matches.indexOf(c)>=featuredArtCount);});const visible=matches.filter(c=>!c.hidden).length;document.querySelector('#art-count').textContent=artCategory==='all'?(artExpanded?`全部 ${artworks.length} 件作品`:`精选 ${featuredArtCount} / 共 ${artworks.length} 件作品`):`${artCategoryNames[artCategory]} · ${visible} 件作品`;const expand=document.querySelector('#expand-art');expand.hidden=artCategory!=='all';expand.setAttribute('aria-expanded',artExpanded);expand.innerHTML=artExpanded?'收起，保留精选作品 <span aria-hidden="true">−</span>':`展开全部 ${artworks.length} 件作品 <span aria-hidden="true">＋</span>`;}
document.querySelectorAll('.art-filter').forEach(button=>button.addEventListener('click',()=>{artCategory=button.dataset.artFilter;document.querySelectorAll('.art-filter').forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);});applyArtFilter();}));
document.querySelector('#expand-art').addEventListener('click',()=>{artExpanded=!artExpanded;applyArtFilter();if(!artExpanded)document.querySelector('#gallery-title').scrollIntoView({block:'start'});});
function updateArtwork(){const a=viewerItems[artIndex];document.querySelector('#art-view-title').textContent=a.title;document.querySelector('#art-view-category').textContent=artCategoryNames[a.category];document.querySelector('.art-view-credit').textContent=a.category==='spatial'?'视觉作品：尹硕。':'字体、排版与视觉合成：尹硕。角色插画使用已有素材。';const img=document.querySelector('#art-view-image');img.src=a.full;img.alt=a.title+'，'+artCategoryNames[a.category]+'作品';img.width=a.width;img.height=a.height;document.querySelector('#art-view-position').textContent=`${artIndex+1} / ${viewerItems.length}`;document.querySelector('#art-full-link').href=a.full;document.querySelector('#art-full-link').setAttribute('aria-label','在新标签页查看 '+a.title+' 大图');}
function openArtwork(id,trigger,fromHero=false){viewerItems=fromHero||artCategory==='all'?artworks:artworks.filter(a=>a.category===artCategory);artIndex=viewerItems.findIndex(a=>a.id===id);if(artIndex<0)return;artTrigger=trigger;updateArtwork();artDialog.showModal();document.querySelector('#close-art').focus();requestAnimationFrame(()=>{if(artDialog.open)window.portfolioMotion?.openImage(trigger,artDialog,document.querySelector('#art-view-image'));});}
artCards.forEach(card=>card.addEventListener('click',()=>openArtwork(card.dataset.art,card)));
document.querySelectorAll('[data-art-open]').forEach(button=>button.addEventListener('click',()=>openArtwork(button.dataset.artOpen,button,true)));
document.querySelector('#close-art').addEventListener('click',()=>artDialog.close());
artDialog.addEventListener('close',()=>{artTrigger?.focus({preventScroll:true});});
function stepArtwork(delta){window.portfolioMotion?.clean(artDialog);artIndex=(artIndex+delta+viewerItems.length)%viewerItems.length;updateArtwork();}
document.querySelector('#prev-art').addEventListener('click',()=>stepArtwork(-1));document.querySelector('#next-art').addEventListener('click',()=>stepArtwork(1));
artDialog.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();stepArtwork(-1);}if(e.key==='ArrowRight'){e.preventDefault();stepArtwork(1);}});
